/// <summary>
///     The <c>AVABPJobsUIBuilder</c> class is the UI builder class for <c>BP-CleanUps</c>
/// </summary>
class AVABPCleanUpUIBuilder extends SysOperationAutomaticUIBuilder
{
    AVABPCleanUpContract   contract;

    DialogField df_AVABPOlderThanNumberOfDays;
    DialogField df_AVABPDateTimeOlderThan;


}

Method.Source:
/// <summary>
///     AVA <c>getContract</c> method.
/// </summary>
/// <returns>
///     <c>AVABPJobsContract</c> as return value
/// </returns>
private AVABPCleanUpContract getContract()
{
    if(!contract)
    {
        contract = this.dataContractObject() as AVABPCleanUpContract;
    }

    return contract;
}

/// <summary>
///     AVA <c>getFromDialog</c> method.
/// </summary>
public void getFromDialog()
{
    super();

    this.getContract().parmAVABPOlderThanNumberOfDays(df_AVABPOlderThanNumberOfDays.value());
    this.getContract().parmAVABPDateTimeOlderThan(df_AVABPDateTimeOlderThan.value());
}

/// <summary>
///     AVA <c>postBuild</c> method.
/// </summary>
public void postBuild()
{
    super();

    // get references to dialog controls after creation
    df_AVABPOlderThanNumberOfDays   = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                        methodStr(AVABPCleanUpContract, parmAVABPOlderThanNumberOfDays));
    df_AVABPDateTimeOlderThan       = this.bindInfo().getDialogField(   this.dataContractObject(),
                                                                        methodStr(AVABPCleanUpContract, parmAVABPDateTimeOlderThan));
}

/// <summary>
///     AVA <c>postRun</c> method.
/// </summary>
public void postRun()
{
    super();

    //modified
    df_AVABPOlderThanNumberOfDays.registerOverrideMethod(   methodStr(FormIntControl, modified),
                                                            methodStr(AVABPCleanUpUIBuilder, modifiedAVABPOlderThanNumberOfDays),
                                                            this);
    df_AVABPDateTimeOlderThan.registerOverrideMethod(       methodstr(FormDateTimeControl, modified),
                                                            methodstr(AVABPCleanUpUIBuilder, modifiedAVABPDateTimeOlderThan),
                                                            this);
}

/// <summary>
///     AVA <c>modifiedAVABPOlderThanNumberOfDays</c> method.
/// </summary>
/// <param name="_df_AVABPOlderThanNumberOfDays">
///     <c>FormIntControl</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean modifiedAVABPOlderThanNumberOfDays(FormIntControl _df_AVABPOlderThanNumberOfDays)
{
    df_AVABPDateTimeOlderThan.value(DateTimeUtil::addDays(DateTimeUtil::newDateTime(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()), 0), -df_AVABPOlderThanNumberOfDays.value()));

    return true;
}

/// <summary>
///     AVA <c>modifiedAVABPDateTimeOlderThan</c> method.
/// </summary>
/// <param name="_df_AVABPDateTimeOlderThan">
///     <c>FormDateTimeControl</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean modifiedAVABPDateTimeOlderThan(FormDateTimeControl _df_AVABPDateTimeOlderThan)
{
    int64       timeDifference;
    int         daysDifference;
    int         divisor;
    utcdatetime dateTimeToday;
    utcdatetime dateTimeCorrected;

    divisor = 24 * 60 * 60; // no of seconds per day

    dateTimeToday       = DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()), 0);
    dateTimeCorrected   = df_AVABPDateTimeOlderThan.value();

    if(dateTimeCorrected > dateTimeToday)
    {
        dateTimeCorrected = dateTimeToday;
        df_AVABPDateTimeOlderThan.value(dateTimeCorrected);
    }

    timeDifference  = DateTimeUtil::getDifference(dateTimeToday, dateTimeCorrected);
    daysDifference  = int642int(timeDifference div divisor);
    if(timeDifference mod divisor >= divisor/2)
    {
        daysDifference += 1;
    }

    df_AVABPOlderThanNumberOfDays.value(daysDifference);

    return true;
}
